  const buf = Buffer.from(await res.arrayBuffer());
  // try envelope
  let envelope = null;
  try { const parsed = JSON.parse(buf.toString("utf8")); if (parsed && typeof parsed === "object" && typeof parsed.code === "number") envelope = parsed; } catch { /* raw bytes */ }
  if (!envelope) {
    if (!res.ok) throw new Error(`fetchResource: HTTP ${res.status ?? "?"} and the body was not an error envelope`);
    return buf;
  }
  if (envelope.code !== 0) throw new Error(envelope.message ?? `fetchResource: bridge error code ${envelope.code}`);
  const { content, encoding } = envelope.data ?? {};
  if (typeof content !== "string") throw new Error(envelope.message ?? "fetchResource: bridge returned code 0 without a content string");
  return encoding === "base64" ? Buffer.from(content, "base64") : Buffer.from(content, "utf8");
}
